func newFactsRetractCommand(opts Options) *cobra.Command {
	var (
		branch  string
		jsonOut bool
		global  bool
	)
	cmd := &cobra.Command{
		Use:   "retract <fact-id>",
		Short: "Mark a fact as retracted (no longer true); pruned later by gc",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			factID := args[0]
			var (
				brainDir       string
				resolvedBranch string
				err            error
			)
			// A fact that can be written and not retracted is a fact you are
			// stuck with. Global facts surface in every repository, so being
			// stuck with a wrong one is worse, not better.
			if global {
				if strings.TrimSpace(branch) != "" {
					return fmt.Errorf("--global and --branch cannot be combined: a global fact is not on a branch")
				}
				brainDir, resolvedBranch, err = resolveGlobalFactsTarget(opts.Env)
			} else {
				_, brainDir, resolvedBranch, err = resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
			}
			if err != nil {
				return err
			}
			now := opts.Now().UTC()
			changed := false
			// Seeded with the id so the event is still identifiable if the
			// record cannot be re-read after the mutation.
			retracted := factRecord{ID: factID}
			if err := withBrainWriteLock(brainDir, func() error {
				facts, err := loadFacts(brainDir, resolvedBranch)
				if err != nil {
					return err
				}
				found, didChange := retractFact(facts, factID, now)
				if !found {
					if global {
						return fmt.Errorf("no global fact %s", factID)
					}
					return fmt.Errorf("no fact %s on %s", factID, resolvedBranch)
				}
				changed = didChange
				if !changed {
					return nil
				}
				// Captured under the lock so the webhook reports the kind and
				// paths of the fact that was actually retracted, rather than an
				// id a subscriber would have to look up through an API that only
				// listens on loopback.
				if i := indexOfFact(facts, factID); i >= 0 {
					retracted = facts[i]
				}
				if err := writeFacts(brainDir, resolvedBranch, facts); err != nil {
					return err
				}
				return updateFactSourceManifestLocked(brainDir, now)
			}); err != nil {
				return err
			}
			// Only on a real transition: re-retracting an already-retracted fact
			// changed nothing, and a subscriber that fired on it would act on
			// news that is not news.
			if changed {
				notifyFactWebhook(cmd.Context(), cmd.ErrOrStderr(), opts, WebhookFactRetracted, resolvedBranch, retracted, now)
			}
			if jsonOut {
				return writeJSON(cmd, map[string]any{"id": factID, "branch": resolvedBranch, "status": factStatusRetracted, "changed": changed})
