	cmd.SetErr(&bytes.Buffer{})
	err := runRemember(context.Background(), cmd, opts,
		rememberCommandOptions{path: "preferences.coding.style", agent: "none", global: true, branch: "main"}, "x")
	if err == nil {
		t.Fatal("--global --branch was accepted")
"}

